import {formatAmount,TRAITS} from './engine.mjs';
import {probabilityText as pct} from './strategy.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=formatAmount;
export function allocationName(m){const n=m.lanes.length;return m.lanes.join('·')+'번 '+(n===1?'단독':n===2?'반반':n===3?'세 명 동액':`${n}명 동액`);}
const stats=m=>{
 const zero=m.payout_bins.filter(x=>x.multiple<1e-10).reduce((s,x)=>s+x.probability,0);
 const profit=m.payout_bins.filter(x=>x.multiple>1+1e-10).reduce((s,x)=>s+x.probability,0);
 return {zero,profit};
};
function payoutTable(m){return `<table class="compact-table"><thead><tr><th>최종 잔액</th><th>시작 대비</th><th>확률</th></tr></thead><tbody>${[...m.payout_bins].reverse().map(x=>`<tr class="${x.multiple<1?'row-loss':''}"><td>${esc(fmt(x.multiple*m.bank))}</td><td>${x.multiple.toFixed(2)}배</td><td>${pct(x.probability)}</td></tr>`).join('')}</tbody></table>`;}
export function renderDashboard(root,data,onApply){
 const s=data.input,ms=[1,2,3].map(n=>data.strategies[n]),winner=ms.reduce((a,b)=>a.expected_final>b.expected_final?a:b);
 const mode=data.recommendationMode||'gain',picked=data.recommended||winner;
 const selected=picked.stakes.map((v,i)=>v>0?i+1:0).filter(Boolean),atRisk=stats(picked);
 const positiveStakes=picked.stakes.filter(v=>v>0),equalStakes=positiveStakes.every(v=>Math.abs(v-positiveStakes[0])<=picked.bank*1e-12);
 const title=picked.invested>0?`${selected.join('·')}번 ${selected.length===1?'단독':!equalStakes?'맞춤 배분':selected.length===2?'반반':'동액 배분'}`:'이번에는 투자 보류';
 root.hidden=false;
 root.innerHTML=`<div class="answer-heading"><span class="pill">이번 경기 · 입력값 기준</span><span class="pill ${s.double?'pill-on':'pill-warn'}">${s.double?'더블 ON · 1등 4배':'더블 OFF · 1등 2배'}</span></div>
 <div class="answer-main"><div><p class="eyebrow">${mode==='gain'?'평균 코인 최대화':mode==='protect'?'잔액 방어 기준':'복리 성장 기준'}</p><h2>${esc(title)}</h2><p class="answer-allocation">${picked.invested>0?picked.stakes.map((v,i)=>v>0?`${i+1}번 ${esc(fmt(v))}`:'').filter(Boolean).join(' · '):'입력한 손실 한도 안에서 양의 기대수익 후보 없음'}${picked.held>0?` · 남김 ${esc(fmt(picked.held))}`:''}</p></div><button class="primary" data-dashboard-recommended ${picked.invested>0?'':'disabled'}>이 배분으로 설정</button></div>
 <div class="answer-kpis"><div><span>평균 최종 잔액</span><strong>${esc(fmt(picked.expected_final))}</strong></div><div><span>현재보다 감소</span><strong>${pct(picked.loss_probability)}</strong></div><div><span>전액 손실</span><strong class="${atRisk.zero>0?'negative':''}">${pct(atRisk.zero)}</strong></div></div>
 <p class="model-caption">모델 추정치 · 실제 발동을 미리 읽은 값이 아닙니다. 모델상 0%도 실제 안전 보장은 아닙니다.</p>
 <div class="section-heading"><h3>단독과 분산, 한눈에 비교</h3><span class="muted">아래 3개는 보유 코인 전액 사용</span></div><div class="strategy-cards">${ms.map((m,i)=>{const x=stats(m);return `<article class="strategy-card ${m===winner?'strategy-top':''}"><div class="strategy-topline"><span>${i===0?'한 명에게':i===1?'두 명에게':'세 명에게'}</span>${m===winner?'<b>평균 회수액 1위</b>':''}</div><h3>${esc(allocationName(m))}</h3><strong class="strategy-mean">${esc(fmt(m.expected_final))}</strong><small>평균 최종 잔액</small><dl><div><dt>코인 증가</dt><dd>${pct(x.profit)}</dd></div><div><dt>코인 감소</dt><dd>${pct(m.loss_probability)}</dd></div><div><dt>전액 손실</dt><dd>${pct(x.zero)}</dd></div><div><dt>한 곳 이상 탈락</dt><dd>${pct(1-m.all_selected_podium_probability)}</dd></div></dl><button class="${m===winner?'primary':'secondary'}" data-dashboard-strategy="${i+1}">이 배분 선택</button><details><summary>받을 금액별 확률</summary>${payoutTable(m)}</details></article>`;}).join('')}</div>
 <article class="head-to-head"><h3>단독 vs 반반, 어느 쪽이 더 받을까?</h3><p class="muted">같은 부스트 조합에서 각각의 투자 패널티를 적용해 최종 잔액을 비교했습니다.</p><div class="h2h-bar" aria-hidden="true"><span style="width:${data.head_to_head.first_more*100}%"></span><span style="width:${data.head_to_head.second_more*100}%"></span><span style="width:${data.head_to_head.equal*100}%"></span></div><div class="h2h-values"><span><i></i>${esc(ms[0].lanes.join('·'))}번 단독 우세 <b>${pct(data.head_to_head.first_more)}</b></span><span><i></i>${esc(ms[1].lanes.join('·'))}번 반반 우세 <b>${pct(data.head_to_head.second_more)}</b></span><span>동일 <b>${pct(data.head_to_head.equal)}</b></span></div><small>합계 100% · 표시 반올림 · 우승 확률과 다른 비교입니다.</small></article>
 <details class="analysis-fold"><summary>투자 조건별 순위 확률 보기</summary>${[1,2].map(n=>{const d=data.strategy_distributions[n],m=data.strategies[n];return `<h4>${esc(allocationName(m))} · ${m.pressure?m.pressure+'번 단독 투자 불이익 반영':'최대 투자액 동률 · 불이익 없음'}</h4><div class="table-wrap"><table><thead><tr><th>번호</th><th>1등</th><th>2등</th><th>3등</th><th>4~6등</th></tr></thead><tbody>${d.rank_probabilities.map((r,i)=>`<tr><td>${i+1}번</td>${r.slice(0,3).map(p=>`<td>${pct(p)}</td>`).join('')}<td>${pct(r.slice(3).reduce((a,b)=>a+b,0))}</td></tr>`).join('')}</tbody></table></div>`;}).join('')}</details>
 <details class="analysis-fold"><summary>지능과 부스트 0~3회 분포</summary><p class="muted">지능별 발동률을 구간마다 적용했습니다. 0회부터 3회까지 모두 포함하며, 성향이 실제로 남는 경우의 보정도 반영합니다.</p><div class="table-wrap"><table><thead><tr><th>번호</th><th>구간 발동률</th><th>0회</th><th>1회</th><th>2회</th><th>3회</th></tr></thead><tbody>${data.boost_counts.map((r,i)=>`<tr><td>${i+1}번</td><td>${pct(data.distribution.boost_probabilities[i])}</td>${r.map(p=>`<td>${pct(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h4>${data.head_to_head.focus_lane}번 단독: 발동 구간에 따른 변화</h4><div class="table-wrap"><table><thead><tr><th>초·중·후반</th><th>패턴 확률</th><th>그때 1등</th><th>그때 4~6등</th></tr></thead><tbody>${data.head_to_head.conditional.map(x=>`<tr><td>${x.flags.map(b=>b?'●':'–').join(' / ')}</td><td>${pct(x.probability)}</td><td>${pct(x.ranks[0])}</td><td>${pct(x.ranks.slice(3).reduce((a,b)=>a+b,0))}</td></tr>`).join('')}</tbody></table></div><p class="muted">● 발동 · – 미발동. ‘그때’는 해당 선수의 패턴이 정해졌다고 가정하고 상대 선수들의 패턴은 확률로 합친 값입니다.</p></details>
 <details class="analysis-fold"><summary>검증 범위와 계산 기준</summary><p>Android 추출 모델에 근거한 계산이며 실제 게임의 장기 승률로 검증된 수치는 아닙니다. 각 투자 조건에서 262,144개 부스트 조합을 지능별 확률로 가중했습니다. 같은 계산 단계의 결승선 통과에는 번호순 처리를 적용합니다.</p><p>과거 영상에서 추정한 부스트 관측률을 공식 대신 임의로 대입하지 않았습니다. 추천은 위에 선택한 목적과 손실 한도를 따르며, 전체 코인 회수액과 전액 손실을 구분합니다.</p></details>`;
 root.querySelector('[data-dashboard-recommended]')?.addEventListener('click',()=>onApply(picked));
 root.querySelectorAll('[data-dashboard-strategy]').forEach(el=>el.addEventListener('click',()=>onApply(data.strategies[el.dataset.dashboardStrategy])));
}
